using System.ComponentModel.DataAnnotations;

namespace Gymnasium.Api.Contracts;

/// <summary>Accepts plain text only; HTML is generated by NewsService.</summary>
public sealed class NewsRequest : IValidatableObject
{
    [Required, StringLength(100), RegularExpression("^[a-z0-9]+(?:-[a-z0-9]+)*$")]
    public required string Slug { get; init; }

    [Required, StringLength(200)]
    public required string Title { get; init; }

    [Required, StringLength(500)]
    public required string Summary { get; init; }

    [Required, StringLength(20000)]
    public required string Content { get; init; }

    public required DateOnly PublishedAt { get; init; }

    public IEnumerable<ValidationResult> Validate(ValidationContext validationContext)
    {
        if (PublishedAt.Year is < 1990 or > 2100)
            yield return new ValidationResult("Use a publication date between 1990 and 2100.", [nameof(PublishedAt)]);
    }
}
